import { useRef, useState } from 'react';
import gsap from 'gsap';
import { useGSAP } from '@gsap/react';

const RUNES = 'ᚠᚢᚦᚨᚱᚲᚷᚹᚺᚾᛁᛃᛇᛈᛉᛊᛏᛒᛖᛗᛚᛜᛞᛟ∆∑∏ΩΨΦΞ';

export default function Preloader({ onComplete }) {
  const root = useRef(null);
  const [count, setCount] = useState(0);
  const [welcome, setWelcome] = useState(false);
  const [glitch, setGlitch] = useState(false);
  const done = useRef(onComplete);
  done.current = onComplete;

  useGSAP(
    () => {
      const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const counter = { v: 0 };

      // runes flicker — cheap interval, killed on cleanup
      let runeTimer = 0;
      const runeEl = root.current?.querySelector('.rune-line');
      if (runeEl && !reduce) {
        runeTimer = window.setInterval(() => {
          let s = '';
          for (let i = 0; i < 6; i++) s += RUNES[(Math.random() * RUNES.length) | 0];
          runeEl.textContent = s;
        }, 60);
      }

      const tl = gsap.timeline({
        defaults: { duration: 0.6, ease: 'power2.out' },
        onComplete: () => done.current?.(),
      });

      tl.addLabel('count', 0);
      tl.to(
        counter,
        {
          v: 100,
          duration: reduce ? 0 : 2.2,
          ease: 'power2.inOut',
          onUpdate: () => setCount(Math.round(counter.v)),
        },
        'count'
      );
      tl.fromTo(
        '.load-bar',
        { scaleX: 0 },
        { scaleX: 1, duration: reduce ? 0 : 2.2, ease: 'power2.inOut' },
        'count'
      );

      tl.addLabel('welcome', '+=0.1');
      tl.call(() => {
        window.clearInterval(runeTimer);
        setWelcome(true);
      }, null, 'welcome');
      tl.fromTo(
        '.welcome-word',
        { y: 80, autoAlpha: 0, rotation: 3 },
        { y: 0, autoAlpha: 1, rotation: 0, duration: reduce ? 0 : 0.7, ease: 'expo.out' },
        'welcome'
      );

      tl.addLabel('glitch', '+=0.55');
      tl.call(() => setGlitch(true), null, 'glitch');

      tl.addLabel('exit', '+=0.6');
      tl.to(
        root.current,
        { yPercent: -100, duration: reduce ? 0 : 0.9, ease: 'expo.inOut' },
        'exit'
      );

      return () => window.clearInterval(runeTimer);
    },
    { scope: root }
  );

  return (
    <div ref={root} className="fixed inset-0 z-[9999] bg-[#0a0a0a] flex items-center justify-center overflow-hidden">
      <style>{`
        @keyframes gl1 {0%{clip-path:inset(20% 0 80% 0);transform:translate(-2px,1px)}100%{clip-path:inset(30% 0 50% 0);transform:translate(1px,-1px)}}
        @keyframes gl2 {0%{clip-path:inset(10% 0 60% 0);transform:translate(2px,-1px)}100%{clip-path:inset(70% 0 10% 0);transform:translate(-2px,1px)}}
        .glitch-text{position:relative}
        .glitch-text::before,.glitch-text::after{content:attr(data-text);position:absolute;inset:0;background:#0a0a0a}
        .glitch-text::before{left:2px;text-shadow:-1px 0 #ff00c1;animation:gl1 .3s infinite linear alternate-reverse}
        .glitch-text::after{left:-2px;text-shadow:-1px 0 #00fff9;animation:gl2 .3s infinite linear alternate-reverse}
      `}</style>

      <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
        <span className="font-syne font-black text-[30vw] leading-none text-white opacity-10 tabular-nums tracking-tighter">
          {count}%
        </span>
      </div>

      <div className="relative z-10 text-center">
        {!welcome ? (
          <div className="rune-line font-mono text-[#FF3333] text-4xl md:text-6xl tracking-[1em] font-bold min-h-[60px]">
            ᚠᚱᚨᚷᛗᚦ
          </div>
        ) : (
          <div
            data-text="WELCOME"
            className={`welcome-word font-syne font-black text-6xl md:text-9xl text-white uppercase tracking-tighter ${
              glitch ? 'glitch-text' : ''
            }`}
          >
            WELCOME
          </div>
        )}
      </div>

      <div className="absolute bottom-10 w-full px-12">
        <div className="w-full h-[1px] bg-white/10 overflow-hidden">
          <div className="load-bar h-full w-full bg-[#FF3333] origin-left scale-x-0" />
        </div>
      </div>
    </div>
  );
}

